# Helper to convert numpy types
def convert_to_serializable(obj):
    if isinstance(obj, dict):
        return {k: convert_to_serializable(v) for k, v in obj.items()}
    elif isinstance(obj, list):
        return [convert_to_serializable(v) for v in obj]
    elif isinstance(obj, (np.integer,)):
        return int(obj)
    elif isinstance(obj, (np.floating,)):
        return float(obj)
    elif isinstance(obj, np.ndarray):
        return obj.tolist()
    else:
        return obj

# Save computed data to JSON for HTML generation
report_data = {
    'kpis': convert_to_serializable(kpis),
    'matches_played': int(matches_played),
    'venues': int(venues),
    'teams': teams_list,
    'total_deliveries': int(total_deliveries),
    'total_runs': int(total_runs),
    'total_wickets': int(total_wickets),
    'total_extras': int(total_extras),
    'batsman_stats': convert_to_serializable(batsman_stats.reset_index().to_dict('records')),
    'bowler_stats': convert_to_serializable(bowler_stats.reset_index().to_dict('records')),
    'dismissals': {str(k): int(v) for k, v in dismissals.to_dict().items()},
    'team_batting': convert_to_serializable(team_batting.reset_index().to_dict('records')),
    'team_bowling': convert_to_serializable(team_bowling.reset_index().to_dict('records')),
    'phase_batting': convert_to_serializable(phase_batting.reset_index().to_dict('records')),
    'venue_stats': convert_to_serializable(venue_stats.reset_index().to_dict('records')),
    'extras_breakdown': {str(k): int(v) for k, v in extras_breakdown.items()},
    'over_runs': convert_to_serializable(over_runs.reset_index().to_dict('records')),
    'worst_discipline': convert_to_serializable(worst_discipline.reset_index().to_dict('records'))
}

with open('/app/output/report_data.json', 'w') as f:
    json.dump(report_data, f, indent=2)

